package br.com.erp;
import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
class ReconciliationTest extends ApiTestSupport {
 String auth,bank;UUID branch,entry;String today;
 @BeforeEach void fixture()throws Exception{auth=token(company);branch=db.queryForObject("SELECT id FROM branch WHERE tenant_id=?",UUID.class,tenant);today=getApi("/api/v1/payables/calendar",auth,200).get("date").asText();bank=account(branch,"BANK","BANK");UUID op=UUID.randomUUID();postApi("/api/v1/treasury/movements",auth,Map.of("requestId",op,"destinationId",bank,"amount","100","note","Depósito de teste"),200);entry=db.queryForObject("SELECT id FROM treasury_entry WHERE tenant_id=? AND operation_id=?",UUID.class,tenant,op);}
 String account(UUID b,String code,String kind)throws Exception{return postApi("/api/v1/treasury/accounts",auth,Map.of("requestId",UUID.randomUUID(),"branchId",b,"code",code,"name","Conta "+code,"kind",kind),201).get("id").asText();}
 Map<String,Object> line(String id,String amount){return Map.of("externalId",id,"postedOn",today,"amount",amount,"description","Descrição do banco");}
 Map<String,Object> input(UUID key,List<?> lines){return Map.of("requestId",key,"accountId",bank,"reference","Extrato de teste","lines",lines);}
 JsonNode imported(String id,String amount)throws Exception{postApi("/api/v1/reconciliation/imports",auth,input(UUID.randomUUID(),List.of(line(id,amount))),201);return getApi("/api/v1/reconciliation/accounts/"+bank+"/lines",auth,200).get("items").iterator().next();}
 JsonNode byExternal(String id)throws Exception{for(var l:getApi("/api/v1/reconciliation/accounts/"+bank+"/lines",auth,200).get("items"))if(l.get("externalId").asText().equals(id))return l;throw new AssertionError();}
 String path(JsonNode l){return "/api/v1/reconciliation/lines/"+l.get("id").asText();}
 Map<String,Object> review(UUID key,long version,UUID entry){var m=new HashMap<String,Object>();m.put("requestId",key);m.put("version",version);m.put("entryId",entry);m.put("note","Conferência manual do extrato");return m;}
 long count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE tenant_id=?",Long.class,tenant);}
 void balance(){assertEquals(0,new BigDecimal("100").compareTo(db.queryForObject("SELECT balance FROM treasury_account WHERE id=?",BigDecimal.class,UUID.fromString(bank))));assertEquals(1,count("treasury_entry"));}
 @Test void importReplayAndOverlappingFilesReuseLinesWithoutChangingBalances()throws Exception{UUID key=UUID.randomUUID();var first=postApi("/api/v1/reconciliation/imports",auth,input(key,List.of(line("ONE","100"))),201);assertEquals(first,postApi("/api/v1/reconciliation/imports",auth,input(key,List.of(line("ONE","100.00"))),201));var second=postApi("/api/v1/reconciliation/imports",auth,input(UUID.randomUUID(),List.of(line("ONE","100"),line("TWO","-20"))),201);assertEquals(1,second.get("newCount").asInt());assertEquals(1,second.get("reusedCount").asInt());assertEquals(2,count("bank_statement_line"));assertEquals(2,count("bank_import"));balance();}
 @Test void changedExternalIdAndImportKeyRollbackEntireBatch()throws Exception{UUID key=UUID.randomUUID();postApi("/api/v1/reconciliation/imports",auth,input(key,List.of(line("Z","100"))),201);postApi("/api/v1/reconciliation/imports",auth,input(key,List.of(line("Z","99"))),409);postApi("/api/v1/reconciliation/imports",auth,input(UUID.randomUUID(),List.of(line("A","1"),line("Z","99"))),409);assertEquals(1,count("bank_statement_line"));assertEquals(1,count("bank_import"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM audit_event WHERE tenant_id=? AND action='BANK_STATEMENT_IMPORTED'",Integer.class,tenant));}
 @Test void matchingReplayResetAndHistoryKeepFinancialLedgerUntouched()throws Exception{var l=imported("ONE","100");assertEquals(1,getApi(path(l)+"/candidates",auth,200).get("total").asInt());UUID key=UUID.randomUUID();var body=review(key,0,entry);var matched=postApi(path(l)+"/match",auth,body,200);assertEquals("MATCHED",matched.get("status").asText());assertEquals(matched,postApi(path(l)+"/match",auth,body,200));postApi(path(l)+"/match",auth,review(UUID.randomUUID(),0,entry),409);postApi(path(l)+"/reset",auth,review(UUID.randomUUID(),1,null),200);var replay=postApi(path(l)+"/match",auth,body,200);assertEquals("UNMATCHED",replay.get("status").asText());assertEquals(2,getApi(path(l)+"/history",auth,200).get("total").asInt());balance();}
 @Test void sameEntryCannotMatchTwoLinesAndWrongSignOrAccountAreRejected()throws Exception{imported("ONE","100");imported("TWO","100");var first=byExternal("ONE");var second=byExternal("TWO");postApi(path(first)+"/match",auth,review(UUID.randomUUID(),0,entry),200);postApi(path(second)+"/match",auth,review(UUID.randomUUID(),0,entry),409);var negative=imported("NEG","-100");postApi(path(negative)+"/match",auth,review(UUID.randomUUID(),0,entry),409);String other=account(branch,"OTHER","BANK");UUID op=UUID.randomUUID();postApi("/api/v1/treasury/movements",auth,Map.of("requestId",op,"destinationId",other,"amount","100","note","Depósito de teste"),200);UUID otherEntry=db.queryForObject("SELECT id FROM treasury_entry WHERE operation_id=?",UUID.class,op);postApi(path(second)+"/match",auth,review(UUID.randomUUID(),0,otherEntry),404);}
 @Test void ignoreAndResetAreVersionedAndRetainAuditHistory()throws Exception{var l=imported("ONE","100");postApi(path(l)+"/ignore",auth,review(UUID.randomUUID(),0,null),200);postApi(path(l)+"/match",auth,review(UUID.randomUUID(),1,entry),409);postApi(path(l)+"/reset",auth,review(UUID.randomUUID(),0,null),409);postApi(path(l)+"/reset",auth,review(UUID.randomUUID(),1,null),200);postApi(path(l)+"/match",auth,review(UUID.randomUUID(),2,entry),200);assertEquals(3,getApi(path(l)+"/history",auth,200).get("total").asInt());balance();}
 @Test void reusedReviewKeyDoesNotChangeAnotherLine()throws Exception{imported("A","100");imported("B","20");var a=byExternal("A");var b=byExternal("B");UUID key=UUID.randomUUID();postApi(path(a)+"/ignore",auth,review(key,0,null),200);postApi(path(b)+"/ignore",auth,review(key,0,null),409);assertEquals("UNMATCHED",getApi(path(b),auth,200).get("status").asText());}
 @Test void csvPreviewIsReadOnlyAndHandlesQuotedFieldsBomAndNegativeAmounts()throws Exception{String csv="\uFEFFexternalId;date;amount;description\r\nA;"+today+";100.00;\"Banco; texto \"\"citado\"\"\"\r\nB;"+today+";-2.50;\"Descrição\nmultilinha\"\r\n";var body=Map.of("requestId",UUID.randomUUID(),"accountId",bank,"reference","CSV teste","content",csv);var preview=postApi("/api/v1/reconciliation/imports/csv/preview",auth,body,200);assertEquals("100.00",preview.get("lines").get(0).get("amount").asText());assertEquals("Banco; texto \"citado\"",preview.get("lines").get(0).get("description").asText());assertEquals(0,count("bank_import"));postApi("/api/v1/reconciliation/imports/csv",auth,body,201);assertEquals(2,count("bank_statement_line"));balance();}
 @Test void invalidCsvOrValuesLeaveNoImportedRows()throws Exception{for(String csv:List.of("bad;headers", "externalId;date;amount;description\nA;"+today+";10,00;Bad", "externalId;date;amount;description\nA;"+today+";1;\"Unclosed", "externalId;date;amount;description\nA;"+today+";1;\"Text\"garbage")){postApi("/api/v1/reconciliation/imports/csv",auth,Map.of("requestId",UUID.randomUUID(),"accountId",bank,"reference","Teste","content",csv),400);}postApi("/api/v1/reconciliation/imports",auth,input(UUID.randomUUID(),List.of(line("A","0"))),400);postApi("/api/v1/reconciliation/imports",auth,input(UUID.randomUUID(),List.of(line("A","1.001"))),400);postApi("/api/v1/reconciliation/imports",auth,input(UUID.randomUUID(),List.of(line("A","1"),line("A","1"))),400);assertEquals(0,count("bank_statement_line"));}
 @Test void onlyBankAccountsAndPastDatesAreAccepted()throws Exception{String cash=account(branch,"CASH","CASH");var body=new HashMap<>(input(UUID.randomUUID(),List.of(line("A","1"))));body.put("accountId",cash);postApi("/api/v1/reconciliation/imports",auth,body,400);var future=new HashMap<>(line("A","1"));future.put("postedOn",LocalDate.parse(today).plusDays(1).toString());postApi("/api/v1/reconciliation/imports",auth,input(UUID.randomUUID(),List.of(future)),400);assertEquals(0,count("bank_import"));}
 @Test void scopedListsCandidatesHistoryAndImportsAreProtected()throws Exception{var l=imported("A","100");UUID other=UUID.fromString(postApi("/api/v1/branches",auth,Map.of("code","OTHER","name","Outra"),201).get("id").asText());UUID user=db.queryForObject("SELECT id FROM app_user WHERE tenant_id=?",UUID.class,tenant);db.update("UPDATE app_user SET all_branches=FALSE WHERE id=?",user);db.update("INSERT INTO user_branch_access(tenant_id,user_id,branch_id) VALUES(?,?,?)",tenant,user,other);for(String suffix:List.of("","/candidates","/history"))getApi(path(l)+suffix,auth,404);for(String suffix:List.of("lines","imports","summary"))getApi("/api/v1/reconciliation/accounts/"+bank+"/"+suffix,auth,404);postApi(path(l)+"/match",auth,review(UUID.randomUUID(),0,entry),404);}
 @Test void tenantAndIndependentImportReviewPermissionsAreEnforced()throws Exception{var l=imported("A","100");String other="other-"+UUID.randomUUID();provisioning.create("Outra",other,"Admin","admin@example.com",password);getApi(path(l),token(other),404);db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='reconciliation:import'",tenant);postApi("/api/v1/reconciliation/imports",auth,input(UUID.randomUUID(),List.of(line("B","1"))),403);postApi(path(l)+"/match",auth,review(UUID.randomUUID(),0,entry),200);db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='reconciliation:review'",tenant);postApi(path(l)+"/reset",auth,review(UUID.randomUUID(),1,null),403);getApi(path(l),auth,200);db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='treasury:read'",tenant);getApi(path(l),auth,403);}
 @Test void concurrentMatchingAndImportRetriesHaveOneEffect()throws Exception{var input=input(UUID.randomUUID(),List.of(line("A","100")));assertEquals(List.of(201,201),concurrent("/api/v1/reconciliation/imports",input,"/api/v1/reconciliation/imports",input));assertEquals(1,count("bank_import"));var l=byExternal("A");var body=review(UUID.randomUUID(),0,entry);assertEquals(List.of(200,200),concurrent(path(l)+"/match",body,path(l)+"/match",body));assertEquals(1,count("bank_statement_review"));balance();}
 @Test void concurrentDifferentLinesCompeteForSameEntry()throws Exception{imported("A","100");imported("B","100");var a=byExternal("A");var b=byExternal("B");assertEquals(List.of(200,409),concurrent(path(a)+"/match",review(UUID.randomUUID(),0,entry),path(b)+"/match",review(UUID.randomUUID(),0,entry)));assertEquals(1,count("bank_statement_review"));balance();}
 List<Integer> concurrent(String p1,Object b1,String p2,Object b2)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var a=pool.submit(()->{gate.await();return status(p1,b1);});var b=pool.submit(()->{gate.await();return status(p2,b2);});gate.countDown();var result=new ArrayList<>(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS)));Collections.sort(result);return result;}}
 int status(String path,Object body)throws Exception{return http.perform(post(path).header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(body))).andReturn().getResponse().getStatus();}
}
